import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.MKFjxsj2.js";const k=JSON.parse('{"title":"H5 访问","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/06-h5-access.md","filePath":"desktop/06-h5-access.md","lastUpdated":1778346950000}'),i={name:"desktop/06-h5-access.md"};function d(r,e,c,n,h,s){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="h5-访问" tabindex="-1">H5 访问 <a class="header-anchor" href="#h5-访问" aria-label="Permalink to &quot;H5 访问&quot;">​</a></h1><p>H5 访问是一个可选的个人/团队使用入口。开启后，你可以把桌面端使用的本地服务通过局域网或自己的反向代理暴露出去，然后在手机浏览器里打开同一套聊天 UI。</p><p>它不是公开 SaaS 登录系统。任何拿到 H5 Token 的人，都可以访问当前桌面端服务暴露的核心聊天能力，所以只应该在你可控的网络、域名和团队范围内使用。</p><h2 id="开启方式" tabindex="-1">开启方式 <a class="header-anchor" href="#开启方式" aria-label="Permalink to &quot;开启方式&quot;">​</a></h2><ol><li>在桌面端打开 <code>设置 -&gt; General -&gt; H5 访问</code>。</li><li>打开 <code>启用 H5 访问</code>。</li><li>点击生成或重新生成 Token。</li><li>立即复制生成的 Token。Token 原文只显示一次；丢失后只能重新生成。</li><li>按你的访问方式填写允许来源： <ul><li>局域网访问：例如 <code>http://192.168.1.20:5173</code></li><li>反向代理访问：例如 <code>https://cc.example.com</code></li></ul></li><li>如果你使用固定域名，可以填写公开访问地址，设置页会据此生成 H5 URL。</li></ol><p>H5 设置保存到 <code>~/.claude/cc-haha/settings.json</code>。系统只保存 Token 哈希，不保存 Token 明文。</p><h2 id="访问地址" tabindex="-1">访问地址 <a class="header-anchor" href="#访问地址" aria-label="Permalink to &quot;访问地址&quot;">​</a></h2><p>浏览器入口使用前端地址加 <code>serverUrl</code> 参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cc.example.com/?serverUrl=https%3A%2F%2Fcc-api.example.com</span></span></code></pre></div><p>如果前端和后端由同一个反向代理路径提供，可以把 <code>serverUrl</code> 指向同一个公开服务根地址。</p><p>首次打开时，H5 页面会要求输入：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Server URL</td><td>桌面端服务或反向代理后的后端地址</td></tr><tr><td>H5 Token</td><td>设置页生成的 Token</td></tr></tbody></table><p>验证成功后，浏览器会把 Server URL 和 Token 保存在当前浏览器的 <code>localStorage</code>，之后自动带上 REST <code>Authorization</code> 和 WebSocket <code>token</code> 参数。</p><h2 id="推荐部署" tabindex="-1">推荐部署 <a class="header-anchor" href="#推荐部署" aria-label="Permalink to &quot;推荐部署&quot;">​</a></h2><h3 id="局域网" tabindex="-1">局域网 <a class="header-anchor" href="#局域网" aria-label="Permalink to &quot;局域网&quot;">​</a></h3><p>适合个人手机测试：</p><ol><li>让后端监听局域网地址或由你自己的代理转发到本机端口。</li><li>在设置页把手机浏览器打开的前端来源加入允许来源。</li><li>手机和电脑连接同一个可信网络。</li><li>手机打开 H5 URL，输入 Token。</li></ol><h3 id="反向代理" tabindex="-1">反向代理 <a class="header-anchor" href="#反向代理" aria-label="Permalink to &quot;反向代理&quot;">​</a></h3><p>适合小团队访问：</p><ol><li>使用 HTTPS 域名代理前端静态资源和后端 API。</li><li>把前端来源加入 H5 允许来源，不要使用通配来源。</li><li>确保 <code>/api/*</code>、<code>/proxy/*</code> 和 <code>/ws/*</code> 都转发到桌面端服务。</li><li>WebSocket 代理需要支持协议升级。</li><li>只把域名分享给可信成员，并单独发送 Token。</li></ol><h2 id="手机体验范围" tabindex="-1">手机体验范围 <a class="header-anchor" href="#手机体验范围" aria-label="Permalink to &quot;手机体验范围&quot;">​</a></h2><p>H5 的第一版优先保证聊天主流程：</p><ul><li>会话列表通过抽屉打开，默认收起。</li><li>聊天区是主界面。</li><li>输入框、发送/停止、附件和权限按钮使用手机可点的尺寸。</li><li><code>@</code> 文件菜单会适配手机宽度。</li><li>Workspace 面板和底部 Terminal 面板在手机宽度下不作为主流程显示。</li></ul><p>桌面端和 Tauri 应用仍保留原来的布局和交互。</p><h2 id="安全注意" tabindex="-1">安全注意 <a class="header-anchor" href="#安全注意" aria-label="Permalink to &quot;安全注意&quot;">​</a></h2><ul><li>H5 默认关闭。</li><li>Token 原文只出现一次。</li><li>远程 API、代理接口和 WebSocket 都需要 H5 Token。</li><li>CORS 只允许设置页配置的来源。</li><li>禁用 H5 或重新生成 Token 后，旧 Token 会失效。</li><li>不要把 H5 暴露到公共网络后再把 Token 发到公开渠道。</li></ul><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>页面提示需要 Token</td><td>在设置页复制最新 Token，重新输入</td></tr><tr><td>Token 无效</td><td>重新生成 Token，并更新手机浏览器里保存的 Token</td></tr><tr><td>无法连接 Server URL</td><td>检查后端地址、端口、防火墙和反向代理</td></tr><tr><td>浏览器被 CORS 拦截</td><td>把当前前端来源加入 H5 允许来源</td></tr><tr><td>WebSocket 连接失败</td><td>检查反向代理是否转发 <code>/ws/*</code> 并启用 WebSocket upgrade</td></tr></tbody></table>',28)])])}const b=t(i,[["render",d]]);export{k as __pageData,b as default};
